Console.Write("Primeiro número: "); var a=decimal.Parse(Console.ReadLine()!); Console.Write("Segundo número: "); var b=decimal.Parse(Console.ReadLine()!); Console.Write("Operação (+ - * /): "); var op=Console.ReadLine(); var resultado=op switch {"+"=>a+b,"-"=>a-b,"*"=>a*b,"/" when b!=0=>a/b,_=>throw new ArgumentException("Operação inválida ou divisão por zero")}; Console.WriteLine($"Resultado: {resultado}");
